$user=trim((string)($_GET['username']??''));if($user===''){http_response_code(400);$user='User Hotspot';}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Traffic History - <?=htmlspecialchars($user,ENT_QUOTES,'UTF-8')?> - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css"><link rel="stylesheet" href="../assets/css/common.css"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><style>body{margin:0}.page{padding:22px;max-width:1200px;margin:auto}.head{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:16px}.title{font-size:22px;font-weight:800;color:var(--text);margin:0}.sub{font-size:11px;color:var(--muted);margin-top:4px}.card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:16px;margin-bottom:12px;box-shadow:var(--shadow-card,0 2px 10px rgba(0,0,0,.04))}.ranges{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:14px}.range,.btn{border:1px solid var(--border);background:var(--card);color:var(--text);border-radius:7px;padding:7px 12px;font-size:11px;text-decoration:none;cursor:pointer}.range.active,.btn.primary{background:var(--primary);border-color:var(--primary);color:#fff}.chart{height:340px}.chart canvas{width:100%;height:100%}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:12px}.kpi{border:1px solid var(--border);border-radius:9px;padding:10px}.kpi b{display:block;font-size:15px;color:var(--text)}.kpi span{font-size:8px;color:var(--muted)}.table{width:100%;border-collapse:collapse;font-size:10px}.table th,.table td{padding:8px;border-bottom:1px solid var(--border);text-align:right;white-space:nowrap}.table th:first-child,.table td:first-child{text-align:left}.table th{color:var(--muted);font-size:9px}.wrap{overflow:auto}@media(max-width:900px){.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:600px){.page{padding:12px}.head{align-items:flex-start;flex-direction:column}.chart{height:260px}.kpis{grid-template-columns:1fr 1fr}}</style></head><body><main class="page"><div class="head"><div><h1 class="title">Traffic History — <?=htmlspecialchars($user,ENT_QUOTES,'UTF-8')?></h1><div id="meta" class="sub">Memuat data...</div></div><div><a class="btn" href="./">← Kembali Hotspot</a></div></div><section class="card"><div class="ranges"><button class="range" data-range="1h">1 Jam</button><button class="range" data-range="6h">6 Jam</button><button class="range active" data-range="24h">24 Jam</button><button class="range" data-range="7d">7 Hari</button><button class="range" data-range="30d">30 Hari</button></div><div class="chart"><canvas id="chart"></canvas></div><div class="kpis"><div class="kpi"><b id="rx">0 B</b><span>RX TERAKHIR</span></div><div class="kpi"><b id="tx">0 B</b><span>TX TERAKHIR</span></div><div class="kpi"><b id="avgD">0 bps</b><span>AVG DOWNLOAD</span></div><div class="kpi"><b id="avgU">0 bps</b><span>AVG UPLOAD</span></div><div class="kpi"><b id="peakD">0 bps</b><span>PEAK DOWNLOAD</span></div><div class="kpi"><b id="peakU">0 bps</b><span>PEAK UPLOAD</span></div></div></section><section class="card"><h2 style="font-size:13px;color:var(--text)">Detail Traffic</h2><div class="wrap"><table class="table"><thead><tr><th>Waktu</th><th>RX Cumulative</th><th>TX Cumulative</th><th>Download</th><th>Upload</th><th>IP</th><th>Interface</th></tr></thead><tbody id="details"><tr><td colspan="7">Memuat...</td></tr></tbody></table></div></section></main><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js"></script><script>const user=<?=json_encode($user,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,api='../api/hotspot_history.php';let range='24h',chart=null,$=id=>document.getElementById(id);function bytes(n){n=Number(n)||0;if(n<1024)return n.toFixed(0)+' B';let u=['KB','MB','GB','TB'],i=-1;do{n/=1024;i++}while(n>=1024&&i<u.length-1);return n.toFixed(n>=100?0:1)+' '+u[i]}function speed(n){n=Number(n)||0;if(n<1000)return n.toFixed(0)+' bps';let u=['Kbps','Mbps','Gbps','Tbps'],i=-1;do{n/=1000;i++}while(n>=1000&&i<u.length-1);return n.toFixed(n>=100?0:1)+' '+u[i]}function draw(d){let ctx=$('chart').getContext('2d');if(chart)chart.destroy();chart=new Chart(ctx,{type:'line',data:{labels:d.labels||[],datasets:[{label:'Download',data:d.download_speed||[],tension:.25,borderWidth:2},{label:'Upload',data:d.upload_speed||[],tension:.25,borderWidth:2,borderDash:[5,4]}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},scales:{y:{ticks:{callback:v=>speed(v)}},x:{ticks:{maxTicksLimit:10}}}}})}function details(rows){$('details').innerHTML=rows?.length?rows.slice(-150).reverse().map(x=>`<tr><td>${x.time}</td><td>${bytes(x.rx)}</td><td>${bytes(x.tx)}</td><td>${speed(x.download_bps)}</td><td>${speed(x.upload_bps)}</td><td>${x.address||'-'}</td><td>${x.interface||'-'}</td></tr>`).join(''):'<tr><td colspan="7">Belum ada histori.</td></tr>'}async function load(r=range){range=r;document.querySelectorAll('.range').forEach(x=>x.classList.toggle('active',x.dataset.range===r));try{let res=await fetch(api+'?username='+encodeURIComponent(user)+'&range='+r+'&t='+Date.now(),{cache:'no-store'}),d=await res.json();if(!res.ok||!d.success)throw Error(d.message||'Gagal mengambil histori');$('meta').textContent=r.toUpperCase()+' • '+d.records+' records';$('rx').textContent=bytes(d.latest_rx);$('tx').textContent=bytes(d.latest_tx);$('avgD').textContent=speed(d.average_download_bps);$('avgU').textContent=speed(d.average_upload_bps);$('peakD').textContent=speed(d.peak_download_bps);$('peakU').textContent=speed(d.peak_upload_bps);draw(d);details(d.details)}catch(e){$('meta').textContent=e.message;draw({});details([])}}document.querySelectorAll('.range').forEach(x=>x.onclick=()=>load(x.dataset.range));load();setInterval(()=>document.visibilityState==='visible'&&load(),10000);</script></body></html>